/// Builtin: normals - select only normal numbers (not zero, infinite, NaN, or subnormal)
fn builtin_normals<W: Clone + AsRef<[u64]>>(value: StandardJson<'_, W>) -> QueryResult<'_, W> {
    if let StandardJson::Number(n) = &value {
        if let Ok(f) = n.as_f64() {
            if f.is_normal() {
                return QueryResult::One(value);
            }
        }
    }
    QueryResult::None
}

/// Builtin: finites - select only finite numbers (not infinite or NaN)
fn builtin_finites<W: Clone + AsRef<[u64]>>(value: StandardJson<'_, W>) -> QueryResult<'_, W> {
    if let StandardJson::Number(n) = &value {
        if let Ok(f) = n.as_f64() {
            if f.is_finite() {
                return QueryResult::One(value);
            }
        }
    }
    QueryResult::None
}

// Phase 13: Iteration control

/// Builtin: limit(n; expr) - output at most n values from expr
fn builtin_limit<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    n_expr: &Expr,
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Evaluate n. Same "no limit at all" branch as `eval_limit` for a
    // negative count/null/bool (#983) -- this function is parser-
    // unreachable today (see #981's investigation), but kept consistent
    // so a future routing change can't silently reintroduce the bug this
    // issue fixed in the live implementation.
    let n_result = eval_single::<W, S>(n_expr, value.clone(), optional);
    let n = match n_result {
        QueryResult::One(v) => {
            if let StandardJson::Number(num) = v {
                num.as_i64().unwrap_or(0) as usize
            } else {
                return QueryResult::Error(EvalError::type_error("number", type_name(&v)));
            }
        }
        QueryResult::Owned(OwnedValue::Int(i)) if i >= 0 => i as usize,
        QueryResult::Owned(OwnedValue::Float(f)) if f >= 0.0 => f as usize,
        QueryResult::Owned(
            OwnedValue::Int(_) | OwnedValue::Float(_) | OwnedValue::Null | OwnedValue::Bool(_),
        ) => return eval_single::<W, S>(expr, value, optional),
        QueryResult::Error(e) => return QueryResult::Error(e),
        _ => return QueryResult::Error(EvalError::type_error("number", "null")),
    };

    if n == 0 {
        return QueryResult::None;
    }

    // `Builtin::Limit` is the internal spelling of the same `limit(n; f)`,
    // differing from `eval_limit` only in always materializing its answer.
    // Same sink, same trailing-control rule (#820).
    let (taken, flow) = each_take_n::<W, S>(expr, value, optional, n);
    let satisfied = taken.len() >= n;
    let values: Vec<OwnedValue> = taken.into_iter().map(Item::into_owned).collect();
    match flow {
        Flow::Stopped { .. } | Flow::Exhausted => owned_vec_to_result(values),
        Flow::Escaped(control) => {
            if satisfied {
                owned_vec_to_result(values)
            } else {
                partial(values, control)
            }
        }
    }
}

/// Builtin: first(expr) - output only the first value from expr (stream version)
fn builtin_first_stream<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // `Builtin::FirstStream` is the internal spelling of the same `first(f)`;
    // it differs from `eval_first_expr` only in always materializing its
    // answer, which is preserved here.
    match each_take_first::<W, S>(expr, value, optional) {
        Ok(Some(item)) => QueryResult::Owned(item.into_owned()),
        Ok(None) => QueryResult::None,
        Err(control) => control_to_result(control),
    }
}

/// Builtin: last(expr) - output only the last value from expr (stream version)
fn builtin_last_stream<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    let result = eval_single::<W, S>(expr, value, optional);
    match result {
        QueryResult::One(v) => QueryResult::Owned(to_owned(&v)),
        QueryResult::OneCursor(c) => QueryResult::Owned(to_owned(&c.value())),
        QueryResult::Owned(v) => QueryResult::Owned(v),
        QueryResult::Many(results) => {
            if let Some(last) = results.into_iter().last() {
                QueryResult::Owned(to_owned(&last))
            } else {
                QueryResult::None
            }
        }
        QueryResult::ManyOwned(results) => {
            if let Some(last) = results.into_iter().last() {
                QueryResult::Owned(last)
            } else {
                QueryResult::None
            }
        }
        QueryResult::None => QueryResult::None,
        QueryResult::Error(e) => QueryResult::Error(e),
        QueryResult::Break(label) => QueryResult::Break(label),
        QueryResult::Halt(code) => QueryResult::Halt(code),
        // Same semantics as `eval_last_expr`: `last` cannot short-circuit,
        // so a `Partial` just surfaces its control, dropping the prefix.
        QueryResult::Partial(_, Control::Error(e)) => QueryResult::Error(e),
        QueryResult::Partial(_, Control::Break(label)) => QueryResult::Break(label),
        QueryResult::Partial(_, Control::Halt(code)) => QueryResult::Halt(code),
    }
}

/// Builtin: nth(n; expr) - output only the nth value from expr (0-indexed, stream version)
fn builtin_nth_stream<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    n_expr: &Expr,
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Evaluate n. jq's own `def nth($n; g): if $n < 0 then error("nth
    // doesn't support negative indices") else ...` -- `null` already falls
    // into the `_` catch-all below and errors (different message text, but
    // the same jq-required outcome); a genuinely negative number silently
    // became index 0 here instead of erroring (#983; verified against jq
    // 1.7.1's own two-arg `nth`).
    let n_result = eval_single::<W, S>(n_expr, value.clone(), optional);
    let n = match n_result {
        QueryResult::One(v) => {
            if let StandardJson::Number(num) = v {
                let f = num.as_f64().unwrap_or(0.0);
                if f < 0.0 {
                    return QueryResult::Error(EvalError::new(
                        "nth doesn't support negative indices",
                    ));
                }
                num.as_i64().map_or(f as usize, |i| i as usize)
            } else {
                return QueryResult::Error(EvalError::type_error("number", type_name(&v)));
            }
        }
        QueryResult::Owned(
            ref owned @ (OwnedValue::Int(_) | OwnedValue::Float(_) | OwnedValue::NumberLiteral(..)),
        ) => {
            let f = owned.as_f64().unwrap_or(0.0);
            if f < 0.0 {
                return QueryResult::Error(EvalError::new("nth doesn't support negative indices"));
            }
            f as usize
        }
        QueryResult::Error(e) => return QueryResult::Error(e),
        // A halt while evaluating `n` must propagate, not be misreported as
        // a type error (#791).
        QueryResult::Halt(code) => return QueryResult::Halt(code),
        QueryResult::Partial(_, Control::Halt(code)) => return QueryResult::Halt(code),
        // #1408: a zero-output `n` (e.g. `nth(empty; .a,.b)`) must make the
        // whole call produce zero output, matching real jq's `n as $n | ...`
        // desugaring -- not fall into the generic type-error catch-all below.
        QueryResult::None => return QueryResult::None,
        _ => return QueryResult::Error(EvalError::type_error("number", "null")),
    };

    // Same sink as `eval_nth_expr`, differing only in always materializing
    // its answer (#820).
    match each_take_nth::<W, S>(expr, value, optional, n) {
        Ok(Some(item)) => QueryResult::Owned(item.into_owned()),
        Ok(None) => QueryResult::None,
        Err(control) => control_to_result(control),
    }
}

/// Builtin: isempty(expr) - returns true if expr produces no outputs
fn builtin_isempty<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // jq: `def isempty(g): label $out | (g|false, break $out), true;`
    //
    // The `break $out` fires on `g`'s *first* output, so `g` is never asked
    // for a second one — that `break` is exactly `Demand::Stop` (#820). Before
    // the sink existed this ran `g` to completion first, which meant a
    // `stderr`/`halt_error` in a later, never-needed branch had already
    // printed, and an `input`/`inputs` there had already *consumed* a document
    // the CLI's driver loop then never processed.
    //
    // The three arms below replace an eight-arm case analysis (#882, #791,
    // #867) whose every oracle fact now falls out of `Flow`'s shape instead of
    // being re-derived per `QueryResult` variant.
    match eval_each::<W, S>(expr, value, optional, &mut |_item| Demand::Stop) {
        // `g` produced an output and we stopped it right there.
        //
        // `pending` is deliberately dropped: it is only ever `Some` when an
        // eager fallback had already raised a trailing control before the
        // stop, and real jq — which would never have evaluated that far —
        // answers `false` regardless. Oracle-confirmed for all three shapes:
        // `isempty(1, error("x"))`, `isempty(1, ("m"|halt_error(3)))` and
        // `label $o | isempty(1, break $o)` all answer `false`, exit 0.
        Flow::Stopped { .. } => QueryResult::Owned(OwnedValue::Bool(false)),

        // `g` ran to exhaustion without ever calling the sink.
        Flow::Exhausted => QueryResult::Owned(OwnedValue::Bool(true)),

        // A *bare* escape: `g`'s very first "output" was itself an
        // error/break/halt, so there is nothing to answer with and all three
        // must propagate rather than be reported as "empty" (#882, #791,
        // #867). `control_to_result` preserves `Halt`/`Break` by construction.
        Flow::Escaped(control) => control_to_result(control),
    }
}

/// The YAML type tag (`!!str`, `!!int`, `!!float`, ...) `builtin_delpaths`'s
/// own yq-mode type check reports for a rejected path component (#1220).
/// Distinguishes `Int`/`Float` where `OwnedValue::type_name()` collapses
/// both to `"number"` — real yq's own check cares about the difference (a
/// plain `!!int` is accepted, a `!!float` never is, even a whole-number-
/// valued one like `1.0` — confirmed live against yq v4.53.3).
///
/// The `!!int`/`!!str` arms are unreachable in practice: the sole call
/// site below only invokes this on a component its own `find` already
/// filtered to exclude `String`/`Int`/`NumberLiteral(Int)`. Both arms stay
/// for match exhaustiveness (no catch-all) rather than being coverage-dead
/// weight to chase.
fn delpaths_component_type_tag(value: &OwnedValue) -> &'static str {
    match value {
        OwnedValue::Null => "!!null",
        OwnedValue::Bool(_) => "!!bool",
        OwnedValue::Int(_) | OwnedValue::NumberLiteral(NumberRepr::Int(_), _) => "!!int",
        OwnedValue::Float(_) | OwnedValue::NumberLiteral(NumberRepr::Float(_), _) => "!!float",
        OwnedValue::String(_) => "!!str",
        OwnedValue::Array(_) => "!!seq",
        OwnedValue::Object(_) => "!!map",
    }
}

/// Builtin: delpaths(paths) - delete multiple paths
fn builtin_delpaths<'a, W: Clone + AsRef<[u64]>, S: EvalSemantics>(
    paths_expr: &Expr,
    value: StandardJson<'a, W>,
    optional: bool,
) -> QueryResult<'a, W> {
    // Evaluate paths expression
    let paths_result = eval_single::<W, S>(paths_expr, value.clone(), optional);
    let paths_owned = match paths_result {
        QueryResult::One(v) => to_owned(&v),
        QueryResult::Owned(v) => v,
        QueryResult::Error(e) => return QueryResult::Error(e),
        // A halt must propagate, not be misreported as "paths must be an
        // array" (#791).
        QueryResult::Halt(code) => return QueryResult::Halt(code),
        QueryResult::Partial(_, Control::Halt(code)) => return QueryResult::Halt(code),
        // Same reasoning for a bare, unresolved `break` (#867 follow-up):
        // must keep unwinding, not be misreported as the same array-type
        // error. Deliberately asymmetric with `Halt` above, though:
        // `Partial(_, Control::Break(_))` (paths_expr already produced a
        // value before breaking) stays on the wildcard arm below, since
        // real jq only ever demands paths_expr's *first* output here and
        // never reaches a later comma branch at all — confirmed via oracle,
        // `delpaths(1, break $out)` in real jq 1.7.1 raises the same "Paths
        // must be specified as an array" error this wildcard already
        // produces, it never even reaches the break.
        QueryResult::Break(label) => return QueryResult::Break(label),
        _ => return QueryResult::Error(EvalError::paths_must_be_array()),
    };

    let mut paths = match paths_owned {
        OwnedValue::Array(p) => p,
        _ => return QueryResult::Error(EvalError::paths_must_be_array()),
    };

    // Every entry must itself be an array before any deletion runs — jq
    // validates the whole list up front, so a bad entry anywhere refuses the
    // call rather than deleting the entries that sort ahead of it:
    // `delpaths([[0],"a"])` and `delpaths(["a",[0]])` both raise, neither
    // deletes `[0]` first.
    for path in &paths {
        if !matches!(path, OwnedValue::Array(_)) {
            return QueryResult::Error(EvalError::path_must_be_array_not(path.type_name()));
        }
    }

    // A NaN component is dropped with the path around it, because it names no
    // element at any depth — `resolve_read_index` refuses it, as jq's `jv_get`
    // does. Leaving it in would do more than waste a walk: since #421,
    // `compare_values` orders NaN as strictly less than every number,
    // including another NaN, so two NaN-headed paths would compare `Less`
    // than *each other* simultaneously — a comparator property `sort_by` is
    // entitled to panic on (`core::slice::sort`'s bidirectional-merge
    // consistency check). Filtering NaN out here keeps this particular
    // `sort_by` call entirely NaN-free, so it never risks that regardless.
    // jq cannot arbitrate either — 1.7.1 loops forever on `delpaths([[nan]])`
    // — so this is pinned by unit test rather than by a golden.
    //
    // yq-mode-only (#1162, widened by #1220): real yq's `delpaths()` accepts
    // only a `!!str`/`!!int` path component -- every other YAML type errors,
    // including a slice-descriptor (`{"start":s,"end":e}`, `path(.[a:b])`'s
    // own output shape, #1162's own narrower repro) that jq mode instead
    // splices through via `delete_paths_under`/`delete_keys`'s own
    // `OwnedValue::Object(desc)` arms below. A whole-number-valued float
    // (`1.0`) is rejected too -- real yq's check is on the YAML type, not
    // the numeric value, confirmed live. Folded into this same `retain`
    // pass rather than a separate loop before it: both checks need to
    // visit every path's every component before any deletion runs.
    //
    // No exemption for a `path()`-sourced float index (#1220 issue thread):
    // yq-mode `path()` is itself a succinctly extension with no upstream
    // behavior (real yq has no `path`/`getpath`/`setpath` at all), so a
    // float index it emits isn't oracle-constrained either way. This check
    // stays strict rather than special-casing that producer, because its
    // own job -- matching real yq's `delpaths()` -- is oracle-backed and
    // takes priority; a `path()` round-trip through `delpaths()` was never
    // a real-yq guarantee to preserve.
    //
    // Deliberately run *unconditionally*, not gated on `keeps` (the NaN
    // survival this `retain` also computes): a NaN-headed path can still
    // carry a genuinely bad-typed component alongside its NaN (e.g.
    // `delpaths([[nan, true]])`), and that component must still be caught
    // even though the NaN itself heads the path for silent removal. The
    // `find` predicate below explicitly exempts a NaN `Float` from being
    // *itself* reported as the offender -- `delpaths([[nan]])` alone still
    // silently drops rather than erroring, preserving the NaN-drop behavior
    // above unchanged. (Gating this on `keeps` would let a co-located
    // non-NaN bad component through unnoticed whenever any NaN shared its
    // path -- confirmed live before this exemption was added.)
    // `rejected_component_tag` keeps only the first offender found (path
    // order, then component order within a path) -- confirmed live that
    // real yq reports whichever type-mismatched component it reaches first
    // when several paths/components each qualify.
    let mut rejected_component_tag: Option<&'static str> = None;
    paths.retain(|path| match path {
        OwnedValue::Array(components) => {
            let keeps = !components
                .iter()
                .any(|key| matches!(key, OwnedValue::Float(f) if f.is_nan()));
            if S::TAG == EvalTag::Yq && rejected_component_tag.is_none() {
                rejected_component_tag = components
                    .iter()
                    .find(|component| {
                        !matches!(component, OwnedValue::Float(f) if f.is_nan())
                            && !matches!(
                                component,
                                OwnedValue::String(_)
                                    | OwnedValue::Int(_)
                                    | OwnedValue::NumberLiteral(NumberRepr::Int(_), _)
                            )
                    })
                    .map(delpaths_component_type_tag);
            }
            keeps
        }
        _ => false,
    });
    if let Some(tag) = rejected_component_tag {
        return QueryResult::Error(EvalError::delpaths_rejects_type(tag));
    }

    // jq sorts the whole path list in its total value order — arrays compare
    // lexicographically — before deleting anything, so the order the caller
    // wrote them in is immaterial: `delpaths([[0],[2]])` and
    // `delpaths([[2],[0]])` are both `[20,40]` on `[10,20,30,40]`. Deleting
    // left to right instead let an earlier deletion shift the array under a
    // later path (#398).
    //
    // `compare_values` *is* that ordering, already shared with `sort` and
    // `unique`, so the paths stay wrapped as `OwnedValue::Array` through the
    // sort and it applies unchanged, rather than a second lexicographic
    // comparator growing here to drift from it. The sort has to be stable, as
    // jq's is: two paths can compare equal and still name different keys,
    // `[[1],[1.0]]` being the pair.
    paths.sort_by(compare_values);

    // Every survivor of the `retain` is an array, so this only re-borrows.
    let paths: Vec<&[OwnedValue]> = paths
        .iter()
        .filter_map(|path| match path {
            OwnedValue::Array(components) => Some(components.as_slice()),
            _ => None,
        })
        .collect();

    // The empty path names the document itself, and sorts before every other
    // array, so only the first entry needs checking: `delpaths([[],[0]])` and
    // `delpaths([[0],[]])` are both `null`.
    let result = match paths.first() {
        None => Ok(to_owned(&value)),
        Some([]) => Ok(OwnedValue::Null),
        Some(_) => delete_paths_sorted(to_owned(&value), &paths, 0),
    };
    match result {
        Ok(v) => QueryResult::Owned(v),
        Err(_) if optional => QueryResult::None,
        Err(e) => e.into(),
    }
}

// Phase 10: Math Functions

/// Helper to get float value from input
fn get_float_value<'a, W: Clone + AsRef<[u64]>>(
    value: &StandardJson<'a, W>,
    optional: bool,
) -> Result<f64, QueryResult<'a, W>> {
    get_float_value_with(value, optional, || {
        EvalError::new("math function requires number")
    })
}

/// Like [`get_float_value`], but with a caller-supplied error for the
/// non-number case — used by `gmtime`/`localtime` to raise jq's own wording
/// instead of the generic math-function message.
fn get_float_value_with<'a, W: Clone + AsRef<[u64]>>(
    value: &StandardJson<'a, W>,
    optional: bool,
    not_a_number: impl FnOnce() -> EvalError,
) -> Result<f64, QueryResult<'a, W>> {
    match value {
        StandardJson::Number(n) => {
            if is_nan_sentinel(n.raw_bytes()) {
                Ok(f64::NAN)
            } else if let Some(negative) = is_infinity_sentinel(n.raw_bytes()) {
                Ok(if negative {
                    f64::NEG_INFINITY
                } else {
                    f64::INFINITY
                })
            } else if let Ok(f) = n.as_f64() {
                Ok(f)
            } else if optional {
                Err(QueryResult::None)
            } else {
                Err(QueryResult::Error(EvalError::new("invalid number")))
            }
        }
        _ if optional => Err(QueryResult::None),
        _ => Err(QueryResult::Error(not_a_number())),
    }
}

// no_std compatible floor: truncate towards negative infinity
fn floor_f64(x: f64) -> f64 {
    let t = x as i64 as f64;
    if x < t {
        t - 1.0
    } else {
        t
    }
}

// no_std compatible ceil: truncate towards positive infinity
fn ceil_f64(x: f64) -> f64 {
    let t = x as i64 as f64;
    if x > t {
        t + 1.0
    } else {
        t
    }
}

// no_std compatible round: round to nearest integer, half away from zero
fn round_f64(x: f64) -> f64 {
    if x >= 0.0 {
        floor_f64(x + 0.5)
    } else {
        ceil_f64(x - 0.5)
    }
}

// no_std compatible sqrt using Newton-Raphson
fn sqrt_f64(x: f64) -> f64 {
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return 0.0;
    }
    let mut guess = x / 2.0;
    for _ in 0..50 {
        let next = (guess + x / guess) / 2.0;
        if (next - guess).abs() < 1e-15 * guess.abs() {
            break;
        }
        guess = next;
    }
    guess
}

/// Builtin: floor
fn builtin_floor<W: Clone + AsRef<[u64]>>(
    value: StandardJson<'_, W>,
    optional: bool,
) -> QueryResult<'_, W> {
    match get_float_value::<W>(&value, optional) {
        Ok(n) if n.is_nan() => QueryResult::Owned(OwnedValue::Float(f64::NAN)),
        Ok(n) => QueryResult::Owned(OwnedValue::Int(floor_f64(n) as i64)),
        Err(r) => r,
    }
}

