    #[test]
    fn test_builtin_join() {
        query!(br#"["a", "b", "c"]"#, r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a,b,c");
            }
        );

        // #1003: a null element contributes an empty-string part -- it is
        // NOT skipped (that was a real, separate pre-existing bug this
        // issue's fix corrected as a side effect of matching jq's own
        // reduce-based definition exactly). Confirmed live against jq
        // 1.7.1: `["a",null,"c"] | join("-")` is `"a--c"`, with the
        // separator still appearing on both sides of the empty part.
        query!(br#"["a", null, "c"]"#, r#"join("-")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a--c");
            }
        );

        // join(s) is [.[] | tostring] joined by s, and .[] over an object
        // iterates its values, so jq accepts an object here as readily as
        // an array (#422).
        query!(br#"{"a": "x", "b": "y"}"#, r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "x,y");
            }
        );
        query!(br"{}", r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );

        // #1003: numbers and booleans stringify via tostring, but arrays and
        // objects are passed raw into the accumulator's `+`, so they surface
        // jq's own binary-op wording ("string (...) and array/object (...)
        // cannot be added") instead of a bespoke join-specific error.
        // Confirmed live against jq 1.7.1.
        query!(br#"[[1, 2], "a"]"#, r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and array ([1,2]) cannot be added");
            }
        );
        query!(br#"["a", [1, 2]]"#, r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"a,\") and array ([1,2]) cannot be added");
            }
        );
        query!(br#"["a", {"x": 1}]"#, r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"a,\") and object ({\"x\":1}) cannot be added");
            }
        );

        // #1003's own repro: a non-string separator surfaces this same
        // accumulator-derived wording too, because the separator is fed
        // through the identical `+` accumulator step as every element --
        // it is never type-checked up front. Confirmed live against jq 1.7.1.
        query!(br"[1, 2]", r"join(1)",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"1\") and number (1) cannot be added");
            }
        );
        query!(br"[1, 2, 3]", r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1,2,3");
            }
        );
        query!(br"[true, false]", r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "true,false");
            }
        );

        // #1003: `join(...)?` suppresses every error path above -- the
        // non-iterable input, the separator-add failure, and the
        // element-add failure -- to None instead of propagating. This is
        // the ancestor `eval_try`'s catch at work (#693), not an
        // `optional`-gated branch inside builtin_join itself -- there isn't
        // one, per the doc comment above. Confirmed live against jq 1.7.1
        // (all three are silently empty there too).
        query!(br"5", r#"join(",")?"#,
            QueryResult::None => {}
        );
        query!(br"[1, 2]", r"join([1, 2])?",
            QueryResult::None => {}
        );
        query!(br#"["a", [1, 2]]"#, r#"join(",")?"#,
            QueryResult::None => {}
        );

        // #1036 review: NaN must stringify the way jq's own `tostring` does
        // (as `null`), not Rust's `f64::to_string()` spelling (`"NaN"`) --
        // an earlier draft of this fix used `owned_to_string` here and
        // regressed this exact case (`join`'s own pre-#1003 code got it
        // right by accident, via `to_json()`). Confirmed live: `nan |
        // tostring` is `"null"` in jq 1.7.1.
        query!(br"1", r#"[., nan] | join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1,null");
            }
        );
    }

    #[test]
    fn test_builtin_join_yq_mode() {
        // #1041, all four confirmed divergences from jq's own algorithm,
        // live-verified against yq v4.53.3.
        //
        // 1. Input must be an array -- an object (jq happily iterates its
        //    values) or any other non-array is rejected outright, with the
        //    same `!!<tag>` spelling `tag` uses.
        yq_query!(br#"{"x": "p", "y": "q"}"#, r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "cannot join with !!map, can only join arrays of scalars");
            }
        );
        yq_query!(br"5", r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "cannot join with !!int, can only join arrays of scalars");
            }
        );
        yq_query!(br#""str""#, r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "cannot join with !!str, can only join arrays of scalars");
            }
        );
        yq_query!(br"null", r#"join(",")"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "cannot join with !!null, can only join arrays of scalars");
            }
        );

        // 2. A non-scalar (array/object) element becomes an empty-string
        //    part instead of erroring or being JSON-encoded.
        yq_query!(br#"[[1, 2], "a"]"#, r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ",a");
            }
        );
        yq_query!(br#"[{"x": 1}, "a"]"#, r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, ",a");
            }
        );

        // A `null` *element*, unlike a `null` *separator* below, still
        // becomes an empty-string part (same as jq's own rule) -- so the
        // separator still appears on both sides of it ("a--c", not "a-c").
        yq_query!(br#"["a", null, "c"]"#, r#"join("-")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a--c");
            }
        );

        // 3. A non-string separator is implicitly stringified instead of
        //    erroring (jq errors here).
        yq_query!(br"[1, 2]", r"join(1)",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "112");
            }
        );
        yq_query!(br"[1, 2]", r"join(true)",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1true2");
            }
        );
        // A container separator stringifies to empty (no separator at all),
        // the same "container -> empty" rule as element handling above.
        yq_query!(br"[1, 2]", r"join([1,2])",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "12");
            }
        );

        // 4. A `null` separator renders as the literal text "null" -- a
        //    real inserted separator, not a no-op. The opposite of how a
        //    `null` *element* is handled above: a genuine asymmetry in
        //    yq's own algorithm, not an inconsistency in this port.
        yq_query!(br#"["x", "y", "z"]"#, r"join(null)",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "xnullynullz");
            }
        );

        // Ordinary cases, unaffected by any of the above, still work.
        yq_query!(br#"["a", "b"]"#, r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "a,b");
            }
        );
        yq_query!(br"[]", r#"join(",")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );
    }

    #[test]
    fn test_builtin_contains() {
        // String contains
        query!(br#""hello world""#, r#"contains("world")"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // Array contains
        query!(br"[1, 2, 3]", r"contains([2])",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // Object contains
        query!(br#"{"a": 1, "b": 2}"#, r#"contains({"a": 1})"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // Same type, no containment: false, not an error.
        query!(br"[1]", r"contains([2])",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
        query!(br"1", r"contains(2)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
    }

    /// One representative value per `OwnedValue` variant, in jq's sort order.
    fn one_of_each_kind() -> Vec<OwnedValue> {
        vec![
            OwnedValue::Null,
            OwnedValue::Bool(false),
            OwnedValue::Bool(true),
            OwnedValue::Int(1),
            OwnedValue::Float(1.5),
            OwnedValue::String("s".to_string()),
            OwnedValue::Array(vec![]),
            OwnedValue::Object(IndexMap::new()),
        ]
    }

    /// [`sort_rank`] must stay a faithful coarsening of [`jq_kind`]: the same
    /// order, with `false`/`true` — and only those — collapsed into one rank.
    ///
    /// Deriving `sort_rank` from `jq_kind` makes this true by construction; the
    /// test exists so that re-expanding either into a hand-written match (there
    /// were three such copies before #358) fails loudly instead of drifting. See
    /// the #106 lesson in `CLAUDE.md`: one definition, plus a test that the call
    /// sites agree.
    #[test]
    fn sort_rank_agrees_with_jq_kind() {
        let values = one_of_each_kind();

        for a in &values {
            for b in &values {
                let same_kind = jq_kind(a) == jq_kind(b);
                let same_rank = sort_rank(a) == sort_rank(b);
                // Ranks may merge kinds, never split them.
                if same_kind {
                    assert!(same_rank, "{a:?} vs {b:?}: same kind, different rank");
                }
                // The bool pair is the *only* place a rank merges two kinds.
                if same_rank && !same_kind {
                    assert!(
                        matches!(a, OwnedValue::Bool(_)) && matches!(b, OwnedValue::Bool(_)),
                        "{a:?} vs {b:?}: ranks merged a pair that is not false/true"
                    );
                }
                // Coarsening preserves order: a merge may turn Less/Greater into
                // Equal, but wherever the ranks still differ they must differ
                // the same way the kinds do.
                if !same_rank {
                    assert_eq!(
                        sort_rank(a).cmp(&sort_rank(b)),
                        jq_kind(a).cmp(&jq_kind(b)),
                        "{a:?} vs {b:?}: rank order disagrees with kind order",
                    );
                }
            }
        }

        // jq's documented order: null < false < true < number < string < array
        // < object, with the two booleans sharing the `boolean` slot.
        let ranks: Vec<u8> = values.iter().map(sort_rank).collect();
        assert_eq!(ranks, vec![0, 1, 1, 2, 2, 3, 4, 5]);
    }

    /// jq errors when the two operands' kinds cannot be compared, rather than
    /// answering `false` (#358).
    ///
    /// This covers the *shape* of the result — which `QueryResult` variant each
    /// outcome lands on — for one case of each. The exhaustive oracle matrix
    /// (nesting, `Int`/`Float`, both truncation boundaries, `?` suppression, and
    /// every case run through the generic evaluator too) lives in
    /// `tests/jq_containment_tests.rs`; add new cases there rather than here, so
    /// there is one place to re-check when jq's behaviour is re-probed.
    #[test]
    fn test_builtin_contains_type_mismatch() {
        query!(br"1", r#"contains("a")"#,
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    r#"number (1) and string ("a") cannot have their containment checked"#
                );
            }
        );

        // `true` and `false` are distinct jq kinds that share the *name*
        // `boolean`, so a mixed pair errors — with both operands called
        // `boolean` — while a matched pair is a plain comparison. Screening on
        // `type_name` would answer `false` for the mixed pair; see `jq_kind`.
        query!(br"true", r"contains(false)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "boolean (true) and boolean (false) cannot have their containment checked"
                );
            }
        );
        query!(br"true", r"contains(true)",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        // A mismatch *inside* a container is still plain false: the screen is
        // top-level only, so `owned_contains` stays total.
        query!(br#"[1,"a"]"#, r#"contains(["a",2])"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(!b);
            }
        );
    }

    #[test]
    fn test_builtin_inside() {
        // inside is the inverse of contains
        query!(br"[2]", r"inside([1, 2, 3])",
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );

        query!(br#"{"a": 1}"#, r#"inside({"a": 1, "b": 2})"#,
            QueryResult::Owned(OwnedValue::Bool(b)) => {
                assert!(b);
            }
        );
    }

    /// `inside` reports the container first — it is `contains` with the operands
    /// swapped, so the *argument* leads the message (#358). Wider coverage is in
    /// `tests/jq_containment_tests.rs`; see `test_builtin_contains_type_mismatch`.
    #[test]
    fn test_builtin_inside_type_mismatch() {
        query!(br"1", r"inside([1])",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "array ([1]) and number (1) cannot have their containment checked"
                );
            }
        );

        // The boolean-kind split reaches `inside` too, argument still first.
        query!(br"true", r"inside(false)",
            QueryResult::Error(e) => {
                assert_eq!(
                    e.message,
                    "boolean (false) and boolean (true) cannot have their containment checked"
                );
            }
        );
    }

