    #[test]
    fn test_builtin_tostring() {
        query!(br"42", "tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "42");
            }
        );

        query!(br"true", "tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "true");
            }
        );

        query!(br"null", "tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );
    }

    /// #1075: a *computed* non-finite float (the bare `nan`/`infinite`
    /// builtins, not a document-sourced literal) must spell itself the way
    /// real jq's own JSON-substitution convention does, not Rust's bare
    /// `f64::Display` -- confirmed live against jq 1.7.1.
    #[test]
    fn test_builtin_tostring_computed_nonfinite_matches_jq_1075() {
        query!(br"null", "nan | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );

        query!(br"null", "infinite | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"null", "-infinite | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-1.7976931348623157e+308");
            }
        );

        query!(br"null", "[nan] | @sh",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );

        query!(br"null", "nan | @uri",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );

        query!(br"null", "infinite | @uri",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e%2B308");
            }
        );

        query!(br"null", "nan | @html",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );

        query!(br"null", r#"nan | "\(.)""#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "null");
            }
        );
    }

    #[test]
    fn test_number_literal_overflow_renders_correctly_not_garbage() {
        // A `NumberLiteral` whose parsed f64 overflows to infinity used to
        // re-render its raw source text through `format_number_jq_compat`,
        // producing garbage like "NaNE+2147483647" (#561), then later
        // "inf"/"-inf" (Rust's own `f64::Display`, still wrong -- #1075).
        //
        // Both signs now take jq mode's `DBL_MAX`-text substitution
        // (`nonfinite_display_string`, #1075) -- this still isn't a full
        // match for real jq, which reformats *both* an overflowed literal's
        // own source text (`1e400 | tostring` -> `"1E+400"`, `-1e400 |
        // tostring` -> `"-1E+400"`, live-verified against jq 1.7.1 for this
        // exact input-document shape -- i.e. the literal typed directly as
        // the JSON document, which is what `query!`'s first argument always
        // is) rather than substituting `DBL_MAX` for either sign; see
        // `numeric_display_string`'s own doc comment and issue #1083 for why
        // that gap is deliberately left open here. (A leading `-` typed
        // *inside a filter expression* instead, e.g. `-1e400 | tostring` as
        // the filter text rather than the input, is a different story --
        // jq's own filter grammar treats that as unary negation on the
        // positive literal, degrading fidelity the same way #1035 already
        // documents for smaller literals -- but that's not the shape any
        // test here exercises.)
        query!(br"1e400", "tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"-1e400", "tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-1.7976931348623157e+308");
            }
        );

        query!(br"1e400", "@uri",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e%2B308");
            }
        );

        query!(br"1e400", "@html",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"1e400", "@sh",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"1e400", r#""\(.)""#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );
    }

    #[test]
    fn test_number_literal_overflow_survives_owned_value_reindex_bridges() {
        // `eval_owned_expr`/`eval_owned_input` (backing `reduce`, `foreach`,
        // `as $x` variable binding via `eval_owned_pipe`) and
        // `owned_to_json_bytes` (backing `with_entries`) each serialize an
        // `OwnedValue` back to JSON text and reparse it to keep evaluating --
        // the same bridge pattern `eval_generic.rs` had. Before switching
        // these to `to_json_for_reindex`, an overflowed `NumberLiteral` was
        // silently turned into JSON `null` by that round-trip (#561); now it
        // survives as the same `DBL_MAX`-text substitution the bare-literal
        // test above uses (#1075) -- these bridges are exactly the reason
        // `numeric_display_string` cannot safely stop substituting here for
        // *any* jq-mode overflowed `NumberLiteral` yet (see its own doc
        // comment and issue #1083): `to_json_for_reindex`'s own `1e999`
        // smuggling literal reparses into a `NumberLiteral` indistinguishable
        // from a real one, so a literal-preserving reformat here would wrongly
        // reformat that internal sentinel too.
        query!(br"1e400", ". as $x | $x | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"-1e400", ". as $x | $x | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "-1.7976931348623157e+308");
            }
        );

        query!(br"1e400", "reduce (1) as $x (.; .) | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br"1e400", "foreach (1) as $x (.; .) | tostring",
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "1.7976931348623157e+308");
            }
        );

        query!(br#"{"a":1e400}"#, "with_entries(.value |= (. | tostring))",
            QueryResult::Owned(OwnedValue::Object(obj)) => {
                assert_eq!(
                    obj.get("a"),
                    Some(&OwnedValue::String("1.7976931348623157e+308".to_string()))
                );
            }
        );
    }

    /// #939: `to_json_for_reindex` (the same bridge #561's test above
    /// exercises) substituted a generic `1e999`/`-1e999` sentinel for *any*
    /// infinite `NumberLiteral`, including a document-sourced overflow
    /// literal that already had real source text of its own - so once
    /// `keys`/`.[]`-style operations routed the value through this bridge,
    /// #930's fix (reformatting a `NumberLiteral`'s own text) had nothing
    /// left to work with, and every overflow literal previewed as the same
    /// sentinel-derived text regardless of its actual digits. Oracle-
    /// verified against real jq 1.7.1: a document literal's own text is
    /// reused directly (matching jq exactly) whenever it's already valid
    /// JSON number syntax, since it's guaranteed to reparse to this same
    /// value either way.
    #[test]
    fn test_document_overflow_literal_preserves_own_text_through_reindex_bridges_939() {
        query!(br"123e400", "reduce (1) as $x (.; .) | keys",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1.23E+402) has no keys");
            }
        );

        query!(br"-1e400", "reduce (1) as $x (.; .) | .[]",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "Cannot iterate over number (-1E+400)");
            }
        );

        query!(br#"{"a":12.34e400}"#, "with_entries(.value |= (. | keys))",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (1.234E+401) has no keys");
            }
        );

        query!(br"0.5e400", "foreach (1) as $x (.; .) | keys",
            QueryResult::Error(e) => {
                assert_eq!(e.message, "number (5E+399) has no keys");
            }
        );
    }

    /// `tonumber` keeps the string's own spelling as a `NumberLiteral`
    /// rather than collapsing it to a bare `Int`/`Float` (#1090): both
    /// oracles preserve it (`"2.50" | tonumber` is `2.50` in jq 1.7.1 and
    /// yq 4.53.3 alike), and in yq mode it is also what keeps the value on
    /// the untagged side of `into_plain_number`'s arithmetic boundary, so a
    /// converted float does not pick up a spurious `!!float` tag.
    #[test]
    fn test_builtin_tonumber() {
        query!(br#""42""#, "tonumber",
            QueryResult::Owned(OwnedValue::NumberLiteral(NumberRepr::Int(n), literal)) => {
                assert_eq!(n, 42);
                assert_eq!(&*literal, "42");
            }
        );

        query!(br#""2.75""#, "tonumber",
            QueryResult::Owned(OwnedValue::NumberLiteral(NumberRepr::Float(f), literal)) => {
                assert!((f - 2.75).abs() < 0.001);
                assert_eq!(&*literal, "2.75");
            }
        );

        // A spelling JSON accepts is echoed verbatim, not renormalized.
        query!(br#""2.50""#, "tonumber",
            QueryResult::Owned(OwnedValue::NumberLiteral(_, literal)) => {
                assert_eq!(&*literal, "2.50");
            }
        );

        // A spelling JSON rejects still falls back to a plain number.
        query!(br#""007""#, "tonumber",
            QueryResult::Owned(v) => {
                assert_eq!(v, OwnedValue::Int(7));
            }
        );

        // Already a number
        query!(br"42", "tonumber",
            QueryResult::Owned(v) => {
                assert_eq!(v, OwnedValue::Int(42));
            }
        );
    }

