    /// #1069: real yq's bare, 2-arg `sub(re; s)` replaces *every* match, not
    /// just the first the way jq's `sub` does -- confirmed live against
    /// real yq v4.53.3 (`"aaa" | sub("a";"X")` => `"XXX"`; jq 1.7.1's
    /// equivalent stays `"Xaa"`, unaffected by this yq-only fix).
    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_sub_yq_mode_replaces_every_match_1069() {
        yq_query!(br#""aaa""#, r#"sub("a"; "X")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "XXX");
            }
        );
        yq_query!(br#""hello world world""#, r#"sub("world"; "there")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "hello there there");
            }
        );

        // jq mode is unaffected -- still first-match-only.
        query!(br#""aaa""#, r#"sub("a"; "X")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "Xaa");
            }
        );
    }

    /// #1069's fix must not widen past the bare 2-arg shape: `gsub` (with
    /// or without its own flags argument) always arrives at
    /// `sub_with_resolved_pattern` with `flags = Some("g"/...)`, never
    /// `None`, so it was already global before this fix and stays that way
    /// unchanged. Confirmed both bare-`gsub` and flagged-`gsub` still
    /// replace every match in yq mode.
    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_gsub_yq_mode_unaffected_by_1069() {
        yq_query!(br#""aaa""#, r#"gsub("a"; "X")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "XXX");
            }
        );
        yq_query!(br#""AAA""#, r#"gsub("a"; "X"; "i")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "XXX");
            }
        );
    }

    /// Pins that the 3-arg `sub(re; s; flags)` form's *own* code path is
    /// untouched by #1069's `flags.is_none()` gate -- that gate identifies
    /// the bare 2-arg shape specifically (`flags == None`), and the 3-arg
    /// form always arrives with `flags == Some(_)`, so it can't
    /// accidentally widen onto #1069's bare-2-arg global-replace rule.
    ///
    /// The values asserted here *do* now match real yq (#1122, fixed):
    /// yq's 3-arg `sub` ignores every argument after the pattern and
    /// replaces every match with the empty string, regardless of what the
    /// flags expression evaluates to -- `"g"`, `""`, and `null` all give
    /// the identical `""` for `"aaa"`, confirmed live against yq v4.53.3
    /// for all three. This was a genuine, separately-filed mystery before
    /// #1122's fix (`yq_sub_arity3_empty_replace`, gated on `S::TAG ==
    /// EvalTag::Yq && flags_expr.is_some()` in `builtin_sub_with_flags`,
    /// *before* this bare-2-arg `global` gate is ever reached) -- this test
    /// now exercises that fix's own dispatch, not just confirms it stays
    /// off a different one.
    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_sub_flags_yq_mode_matches_oracle_1122() {
        yq_query!(br#""aaa""#, r#"sub("a"; "X"; "g")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );
        yq_query!(br#""aaa""#, r#"sub("a"; "X"; "")"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );
        yq_query!(br#""aaa""#, r#"sub("a"; "X"; null)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_sub_gsub_replacement_accumulator_wording_1034() {
        // #1034: real jq's sub/gsub (`src/builtin.jq`) build each match's
        // output via `$gap + $inserts[$ix]` -- a genuine `+` against the
        // preceding gap text, not a bespoke "must be a string" check. A
        // non-string replacement now surfaces jq's own binary-op wording,
        // naming the gap (not the whole input) as the left operand.
        // Confirmed live against jq 1.7.1.
        query!(br#""a""#, r#"sub("a"; 5)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and number (5) cannot be added");
            }
        );
        query!(br#""aa""#, r#"gsub("a"; 5)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and number (5) cannot be added");
            }
        );
        // The gap is whatever text precedes the match, not always empty --
        // confirms the error names the *local* gap, not the accumulated
        // output so far.
        query!(br#""hello""#, r#"sub("(?<x>l+)"; 5)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"he\") and number (5) cannot be added");
            }
        );
        // Array/object/bool replacements surface the same wording, matching
        // join's #1003 divergence from `tostring`-style leniency.
        query!(br#""a""#, r#"sub("a"; [1, 2])"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and array ([1,2]) cannot be added");
            }
        );
        query!(br#""a""#, r#"sub("a"; {"x": 1})"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and object ({\"x\":1}) cannot be added");
            }
        );
        // A `null` replacement is jq's own `+`-identity, not an error --
        // deletes the match, keeping only the gap. Confirmed live.
        query!(br#""abc""#, r#"sub("a"; null)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bc");
            }
        );
        // `sub(...)?` still suppresses the error to None, same #693/#928
        // reasoning as #1003's join(...)? -- the ancestor eval_try's catch,
        // not a locally forced `optional`.
        query!(br#""a""#, r#"sub("a"; 5)?"#,
            QueryResult::None => {}
        );
        // `isvalid` reports `false` here too, via its own error-catching
        // (it evaluates with `optional: false`, not forced -- `builtin_isvalid`
        // ignores its own `optional` parameter entirely, per its doc
        // comment), not through any `optional`-gated arm inside
        // `combine_sub_gap` -- there isn't one, per that function's own doc
        // comment above.
        query!(br#""a""#, r#"isvalid(sub("a"; 5))"#,
            QueryResult::Owned(OwnedValue::Bool(false)) => {}
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_gsub_replacement_type_error_aborts_before_later_match_1034() {
        // #1050 review: an earlier, two-pass version of #1034's fix (collect
        // every match's evaluated replacement first, validate types in a
        // second pass) broke jq's strict left-to-right reduce semantics --
        // a later match's replacement filter (including its own side
        // effects / genuine error()) would run even though an earlier
        // match's type mismatch should have aborted the whole call first.
        // Confirmed live against jq 1.7.1: this errors on match "a"'s type
        // mismatch, and match "b"'s error("second ran") never fires.
        query!(br#""ab""#, r#"gsub("(?<x>[ab])"; if .x == "a" then 5 else error("second ran") end)"#,
            QueryResult::Error(e) => {
                assert_eq!(e.message, "string (\"\") and number (5) cannot be added");
            }
        );
    }

    #[cfg(feature = "regex")]
    #[test]
    fn test_regex_sub_yq_mode_stringifies_non_string_replacement_1052() {
        // #1052: real yq's own sub/gsub coercion diverges from jq's
        // `+`-based rules -- confirmed live against yq v4.53.3: a scalar
        // non-string replacement stringifies and concatenates instead of
        // erroring, while an array/object replacement contributes an
        // *empty* string, not a JSON representation like `tostring()`
        // would give.
        yq_query!(br#""abc""#, r#"sub("a"; 5)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "5bc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; 5.5)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "5.5bc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; null)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "nullbc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; true)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "truebc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; false)"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "falsebc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; [1,2])"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; {"x":1})"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bc");
            }
        );
        yq_query!(br#""abc""#, r#"sub("a"; [])"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "bc");
            }
        );
        // An *empty* object is the one exception to the container-is-empty
        // rule: it stringifies to the literal text "{}", not "" the way an
        // empty array or a non-empty object both do (confirmed live).
        yq_query!(br#""abc""#, r#"sub("a"; {})"#,
            QueryResult::Owned(OwnedValue::String(s)) => {
                assert_eq!(s, "{}bc");
            }
        );
        // Never errors any more, so isvalid reports true (was false
        // pre-#1052).
        yq_query!(br#""abc""#, r#"isvalid(sub("a"; 5))"#,
            QueryResult::Owned(OwnedValue::Bool(true)) => {}
        );
    }

