    // ========== Phase 22: load(file) tests ==========

    #[cfg(feature = "std")]
    mod load_tests {
        use super::*;
        use std::fs;

        fn with_temp_file<F, R>(name: &str, content: &str, f: F) -> R
        where
            F: FnOnce(&str) -> R,
        {
            let path = format!("/tmp/succinctly_test_{name}");
            fs::write(&path, content).unwrap();
            let result = f(&path);
            let _ = fs::remove_file(&path);
            result
        }

        #[test]
        fn test_load_json_file() {
            with_temp_file(
                "load_test.json",
                r#"{"name": "test", "value": 42}"#,
                |path| {
                    let json_bytes: &[u8] = b"null";
                    let index = JsonIndex::build(json_bytes);
                    let cursor = index.root(json_bytes);
                    let query = format!(r#"load("{path}")"#);
                    let expr = parse(&query).unwrap();
                    match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                        QueryResult::Owned(OwnedValue::Object(obj)) => {
                            assert_eq!(
                                obj.get("name"),
                                Some(&OwnedValue::String("test".to_string()))
                            );
                            assert_eq!(obj.get("value"), Some(&OwnedValue::Int(42)));
                        }
                        other => panic!("unexpected result: {other:?}"),
                    }
                },
            );
        }

        #[test]
        fn test_load_yaml_file() {
            with_temp_file("load_test.yaml", "name: test\nvalue: 42\n", |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        assert_eq!(
                            obj.get("name"),
                            Some(&OwnedValue::String("test".to_string()))
                        );
                        assert_eq!(obj.get("value"), Some(&OwnedValue::Int(42)));
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_yml_extension() {
            with_temp_file("load_test.yml", "items:\n  - a\n  - b\n", |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        let items = obj.get("items").unwrap();
                        match items {
                            OwnedValue::Array(arr) => {
                                assert_eq!(arr.len(), 2);
                                assert_eq!(arr[0], OwnedValue::String("a".to_string()));
                                assert_eq!(arr[1], OwnedValue::String("b".to_string()));
                            }
                            _ => panic!("expected array"),
                        }
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_nonexistent_file() {
            let json_bytes: &[u8] = b"null";
            let index = JsonIndex::build(json_bytes);
            let cursor = index.root(json_bytes);
            let expr = parse(r#"load("/tmp/nonexistent_file_12345.yaml")"#).unwrap();
            match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                QueryResult::Error(err) => {
                    assert!(
                        err.message.contains("Failed to read file")
                            || err.message.contains("No such file")
                    );
                }
                other => panic!("expected error, got: {other:?}"),
            }
        }

        #[test]
        fn test_load_optional_nonexistent() {
            // Use try-catch for optional behavior since ? operator applies to field access
            let json_bytes: &[u8] = b"null";
            let index = JsonIndex::build(json_bytes);
            let cursor = index.root(json_bytes);
            let expr = parse(r#"try load("/tmp/nonexistent_file_12345.yaml") catch null"#).unwrap();
            match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                QueryResult::Owned(OwnedValue::Null) => {}
                other => panic!("expected null, got: {other:?}"),
            }
        }

        #[test]
        fn test_load_with_try_catch() {
            let json_bytes: &[u8] = b"null";
            let index = JsonIndex::build(json_bytes);
            let cursor = index.root(json_bytes);
            let expr =
                parse(r#"try load("/tmp/nonexistent_file_12345.yaml") catch "not found""#).unwrap();
            match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                QueryResult::Owned(OwnedValue::String(s)) => {
                    assert_eq!(s, "not found");
                }
                other => panic!("expected 'not found', got: {other:?}"),
            }
        }

        #[test]
        fn test_load_combined_with_input() {
            with_temp_file("config.yaml", "setting: enabled\n", |path| {
                let json_bytes: &[u8] = br#"{"name": "main"}"#;
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#". + {{config: load("{path}")}}"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        assert_eq!(
                            obj.get("name"),
                            Some(&OwnedValue::String("main".to_string()))
                        );
                        let config = obj.get("config").unwrap();
                        match config {
                            OwnedValue::Object(cfg) => {
                                assert_eq!(
                                    cfg.get("setting"),
                                    Some(&OwnedValue::String("enabled".to_string()))
                                );
                            }
                            _ => panic!("expected config to be object"),
                        }
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_multi_document_yaml() {
            with_temp_file("multi.yaml", "---\nname: doc1\n---\nname: doc2\n", |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Array(arr)) => {
                        assert_eq!(arr.len(), 2);
                        match &arr[0] {
                            OwnedValue::Object(obj) => {
                                assert_eq!(
                                    obj.get("name"),
                                    Some(&OwnedValue::String("doc1".to_string()))
                                );
                            }
                            _ => panic!("expected first doc to be object"),
                        }
                        match &arr[1] {
                            OwnedValue::Object(obj) => {
                                assert_eq!(
                                    obj.get("name"),
                                    Some(&OwnedValue::String("doc2".to_string()))
                                );
                            }
                            _ => panic!("expected second doc to be object"),
                        }
                    }
                    other => panic!("expected array of documents, got: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_with_dynamic_path() {
            with_temp_file("dynamic.json", r#"{"loaded": true}"#, |path| {
                // Input contains the path to load
                let json_bytes = format!(r#"{{"path": "{path}"}}"#);
                let json_bytes = json_bytes.as_bytes();
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let expr = parse(r"load(.path)").unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        assert_eq!(obj.get("loaded"), Some(&OwnedValue::Bool(true)));
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        // ========== #224: explicit tag resolution in yaml_value_to_owned ==========

        #[test]
        fn test_load_yaml_explicit_tag_resolution() {
            // An explicit core-schema tag forces the resolved type regardless of
            // what the quoting/plain-scalar shape would otherwise imply: `!!null
            // "~"` and `!!bool "yes"` are quoted (so unquoted plain-scalar
            // resolution never runs), and `!!str 1` is unquoted (so plain-scalar
            // resolution would otherwise produce a number) - the tag wins in
            // every case.
            // `12.5` rather than `3.14`: clippy's `approx_constant` lint flags
            // float literals close to well-known math constants like PI.
            // `f: !custom "5"` isn't one of the 5 core-schema tags, so
            // `resolve_tagged` returns `None` and the code must fall through
            // past the tag check to the quoted-string-preservation check
            // below it, staying a string rather than resolving.
            let yaml = "a: !!null \"~\"\n\
                        b: !!bool \"yes\"\n\
                        c: !!int \"42\"\n\
                        d: !!float \"12.5\"\n\
                        e: !!str 1\n\
                        f: !custom \"5\"\n";
            with_temp_file("load_test_explicit_tags.yaml", yaml, |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        assert_eq!(obj.get("a"), Some(&OwnedValue::Null));
                        assert_eq!(obj.get("b"), Some(&OwnedValue::Bool(true)));
                        assert_eq!(obj.get("c"), Some(&OwnedValue::Int(42)));
                        assert_eq!(obj.get("d"), Some(&OwnedValue::Float(12.5)));
                        assert_eq!(obj.get("e"), Some(&OwnedValue::String("1".to_string())));
                        assert_eq!(obj.get("f"), Some(&OwnedValue::String("5".to_string())));
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_yaml_explicit_tag_on_bare_dash_deferred_sequence_item_835() {
            // #835: `yaml_value_to_owned`'s `Sequence` arm used to walk
            // elements via the raw `uncons_cursor` (rather than
            // `uncons_resolved_cursor`), and its own `explicit_tag()` check
            // doesn't resolve a bare `-` sequence-item wrapper itself (a
            // deliberate hot-path perf trade-off elsewhere) - so a totally
            // bare `-` item's own explicit tag, deferred to the next line,
            // was silently dropped: `!!str 5` loaded as the number `5`
            // instead of the string `"5"`.
            let yaml = "-\n  !!str 5\n";
            with_temp_file("load_test_bare_dash_tag_835.yaml", yaml, |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Array(items)) => {
                        assert_eq!(items, vec![OwnedValue::String("5".to_string())]);
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_yaml_quoted_string_not_coerced_without_tag() {
            // Without an explicit tag, a quoted scalar is kept as a string even
            // though its content looks numeric - only an untagged *plain*
            // scalar goes through resolve_plain's type inference.
            with_temp_file(
                "load_test_quoted_no_tag.yaml",
                "quoted: \"42\"\nplain: 42\n",
                |path| {
                    let json_bytes: &[u8] = b"null";
                    let index = JsonIndex::build(json_bytes);
                    let cursor = index.root(json_bytes);
                    let query = format!(r#"load("{path}")"#);
                    let expr = parse(&query).unwrap();
                    match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                        QueryResult::Owned(OwnedValue::Object(obj)) => {
                            assert_eq!(
                                obj.get("quoted"),
                                Some(&OwnedValue::String("42".to_string()))
                            );
                            assert_eq!(obj.get("plain"), Some(&OwnedValue::Int(42)));
                        }
                        other => panic!("unexpected result: {other:?}"),
                    }
                },
            );
        }

        #[test]
        fn test_load_yaml_non_string_mapping_key() {
            // A non-scalar (sequence) explicit key falls through the
            // `YamlValue::String` arm of the key match and is instead converted
            // recursively via yaml_value_to_owned(...).to_json() - so the
            // resulting object key is the compact JSON rendering of the key,
            // `[1,2]` (no spaces; see OwnedValue::to_json's Array case).
            //
            // Uses a block-sequence explicit key (`? - 1` / `  - 2`) rather
            // than a flow-sequence key (`? [1, 2]`): `parse_explicit_key`'s `[`/`{`
            // arms wrap `parse_flow_sequence`/`parse_flow_mapping` in an extra,
            // untyped `write_bp_open`/`write_bp_close` pair even though those
            // callees already open and close their own container node, so a
            // flow-sequence explicit key currently decodes as a sequence
            // wrapping the real sequence (`[[1,2]]`) instead of the key itself.
            // That double-wrap predates this PR (`a7384db6`, explicit-key
            // support) and is unrelated to tag resolution, so it's left alone
            // here - reported separately rather than fixed as a drive-by.
            with_temp_file(
                "load_test_complex_key.yaml",
                "? - 1\n  - 2\n: value\n",
                |path| {
                    let json_bytes: &[u8] = b"null";
                    let index = JsonIndex::build(json_bytes);
                    let cursor = index.root(json_bytes);
                    let query = format!(r#"load("{path}")"#);
                    let expr = parse(&query).unwrap();
                    match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                        QueryResult::Owned(OwnedValue::Object(obj)) => {
                            assert_eq!(obj.len(), 1);
                            assert_eq!(
                                obj.get("[1,2]"),
                                Some(&OwnedValue::String("value".to_string()))
                            );
                        }
                        other => panic!("unexpected result: {other:?}"),
                    }
                },
            );
        }

        #[test]
        fn test_load_yaml_alias_resolution() {
            with_temp_file("load_test_alias.yaml", "a: &x hello\nb: *x\n", |path| {
                let json_bytes: &[u8] = b"null";
                let index = JsonIndex::build(json_bytes);
                let cursor = index.root(json_bytes);
                let query = format!(r#"load("{path}")"#);
                let expr = parse(&query).unwrap();
                match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                    QueryResult::Owned(OwnedValue::Object(obj)) => {
                        assert_eq!(obj.get("a"), Some(&OwnedValue::String("hello".to_string())));
                        assert_eq!(obj.get("b"), Some(&OwnedValue::String("hello".to_string())));
                    }
                    other => panic!("unexpected result: {other:?}"),
                }
            });
        }

        #[test]
        fn test_load_yaml_alias_preserves_tag_on_anchored_node() {
            // yaml_value_to_owned's Alias arm recurses on the *target cursor*
            // (`yaml_value_to_owned(target_cursor)`), not a bare value, so a tag
            // sitting on the anchored node survives the alias hop - matching
            // yq_runner.rs's yaml_to_owned_value and
            // tests/yq_cli_tests.rs::test_yaml_anchored_tag_in_seq_item_resolves.
            with_temp_file(
                "load_test_alias_tag.yaml",
                "a: &x !!int \"5\"\nb: *x\n",
                |path| {
                    let json_bytes: &[u8] = b"null";
                    let index = JsonIndex::build(json_bytes);
                    let cursor = index.root(json_bytes);
                    let query = format!(r#"load("{path}")"#);
                    let expr = parse(&query).unwrap();
                    match eval::<Vec<u64>, JqSemantics>(&expr, cursor) {
                        QueryResult::Owned(OwnedValue::Object(obj)) => {
                            assert_eq!(obj.get("a"), Some(&OwnedValue::Int(5)));
                            assert_eq!(obj.get("b"), Some(&OwnedValue::Int(5)));
                        }
                        other => panic!("unexpected result: {other:?}"),
                    }
                },
            );
        }
    }

    // ========== #360: the unresolved-computed-key guards ==========

    /// Every path walker refuses an unresolved [`Expr::IndexExpr`], loudly.
    ///
    /// [`resolve_dynamic_indexes`] rewrites each computed key into the static
    /// component it denotes before any of these run, so none of these arms can
    /// fire through the public API — which is exactly why they need a test of
    /// their own. They exist so that a *new* path context wired up without
    /// that pre-pass fails where the mistake is, instead of blaming the user's
    /// filter through the `_` catch-alls ("invalid path component", "cannot use
    /// expression as …") or, in [`walk_path`], silently emitting no path at
    /// all. Nothing else pins that promise: the wording *is* the signal that an
    /// install point has gone missing.
    mod computed_key_guards {
        use super::*;

        /// `.[$k]` left unresolved — what each walker below is handed.
        fn unresolved() -> Expr {
            Expr::index_by(Expr::Identity, Expr::Var("k".to_string()))
        }

        #[test]
        fn test_set_path_refuses_an_unresolved_key() {
            let mut root = OwnedValue::Null;
            let err =
                set_path(&mut root, &unresolved(), OwnedValue::Int(1), false, false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed index in assignment path"
            );
        }

        #[test]
        fn test_get_path_mut_refuses_an_unresolved_key() {
            let mut root = OwnedValue::Null;
            let err = get_path_mut(&mut root, &[unresolved()], false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed index in path component"
            );
        }

        #[test]
        fn test_update_path_refuses_an_unresolved_key() {
            let mut root = OwnedValue::Null;
            let err =
                update_path::<JqSemantics>(&mut root, &unresolved(), &Expr::Identity, false, false)
                    .unwrap_err();
            let EvalEscape::Error(err) = err else {
                panic!("expected EvalEscape::Error, got {err:?}");
            };
            assert_eq!(
                err.message,
                "internal error: unresolved computed index in update path"
            );
        }

        #[test]
        fn test_delete_at_path_refuses_an_unresolved_key() {
            let mut root = OwnedValue::Null;
            let err = delete_at_path(&mut root, &unresolved(), false, false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed index in delete path"
            );
        }

        // [`walk_path`] does have an error channel, but a computed key that
        // reaches it is a wiring bug rather than anything the user's filter
        // did, so its guard stays a `debug_assert!` — which only fires in a
        // build that has them enabled.

        #[test]
        #[cfg(debug_assertions)]
        #[should_panic(expected = "unresolved computed index reached path tracking")]
        fn test_path_tracking_refuses_an_unresolved_key() {
            let mut reached = Vec::new();
            let _ = walk_path::<JqSemantics>(
                &unresolved(),
                &OwnedValue::Null,
                &[],
                &mut reached,
                false,
            );
        }

        /// The same guard reached mid-pipe rather than as the last step —
        /// the position that used to have a walker, and a wording, of its own.
        #[test]
        #[cfg(debug_assertions)]
        #[should_panic(expected = "unresolved computed index reached path tracking")]
        fn test_path_tracking_refuses_an_unresolved_key_mid_pipe() {
            let mut reached = Vec::new();
            let pipe = Expr::Pipe(vec![unresolved(), Expr::Field("a".to_string())]);
            let _ = walk_path::<JqSemantics>(&pipe, &OwnedValue::Null, &[], &mut reached, false);
        }
    }

    // ========== #499: the unresolved-computed-slice guards ==========

    /// Same reasoning as [`computed_key_guards`], one level up: every path
    /// walker refuses an unresolved [`Expr::SliceExpr`] just as loudly as it
    /// refuses an unresolved [`Expr::IndexExpr`], and for the same reason —
    /// [`resolve_dynamic_indexes`] rewrites a computed slice into its static
    /// components before any of these run, so a hit here means a new path
    /// context was wired up without going through that pre-pass.
    mod computed_slice_guards {
        use super::*;

        /// `.[$a:$b]` left unresolved — what each walker below is handed.
        fn unresolved() -> Expr {
            Expr::slice_by(
                Expr::Identity,
                Some(Expr::Var("a".to_string())),
                Some(Expr::Var("b".to_string())),
            )
        }

        #[test]
        fn test_set_path_refuses_an_unresolved_slice() {
            let mut root = OwnedValue::Null;
            let err =
                set_path(&mut root, &unresolved(), OwnedValue::Int(1), false, false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed slice in assignment path"
            );
        }

        #[test]
        fn test_get_path_mut_refuses_an_unresolved_slice() {
            let mut root = OwnedValue::Null;
            let err = get_path_mut(&mut root, &[unresolved()], false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed slice in path component"
            );
        }

        #[test]
        fn test_update_path_refuses_an_unresolved_slice() {
            let mut root = OwnedValue::Null;
            let err =
                update_path::<JqSemantics>(&mut root, &unresolved(), &Expr::Identity, false, false)
                    .unwrap_err();
            let EvalEscape::Error(err) = err else {
                panic!("expected EvalEscape::Error, got {err:?}");
            };
            assert_eq!(
                err.message,
                "internal error: unresolved computed slice in update path"
            );
        }

        #[test]
        fn test_delete_at_path_refuses_an_unresolved_slice() {
            let mut root = OwnedValue::Null;
            let err = delete_at_path(&mut root, &unresolved(), false, false).unwrap_err();
            assert_eq!(
                err.message,
                "internal error: unresolved computed slice in delete path"
            );
        }

        #[test]
        #[cfg(debug_assertions)]
        #[should_panic(expected = "unresolved computed slice reached path tracking")]
        fn test_path_tracking_refuses_an_unresolved_slice() {
            let mut reached = Vec::new();
            let _ = walk_path::<JqSemantics>(
                &unresolved(),
                &OwnedValue::Null,
                &[],
                &mut reached,
                false,
            );
        }

        /// The same guard reached mid-pipe rather than as the last step.
        #[test]
        #[cfg(debug_assertions)]
        #[should_panic(expected = "unresolved computed slice reached path tracking")]
        fn test_path_tracking_refuses_an_unresolved_slice_mid_pipe() {
            let mut reached = Vec::new();
            let pipe = Expr::Pipe(vec![unresolved(), Expr::Field("a".to_string())]);
            let _ = walk_path::<JqSemantics>(&pipe, &OwnedValue::Null, &[], &mut reached, false);
        }
    }

    /// #1326: `path()` keeps a float slice bound's own spelling, the same
    /// way #1088 already does for a float array *index* -- every case here
    /// is oracle-verified against real jq 1.7.1.
    #[test]
    fn test_path_reports_a_float_slice_bound_verbatim_1326() {
        // The issue's own primary repro: a non-whole float bound, which
        // cannot fold at parse time (`fold_index_key` only folds a
        // whole-valued float, #1061) and so exercises the *dynamic*
        // `Expr::SliceExpr` resolution path, not the static one.
        query!(br"[1,2,3,4,5]", r"path(.[1.5:3.5])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3.5}]"#);
            }
        );
        // A whole-valued float bound *does* fold at parse time, exercising
        // the static `Expr::SliceNumber` path instead -- both routes must
        // agree.
        query!(br"[1,2,3,4,5]", r"path(.[1.0:3.0])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.0,"end":3.0}]"#);
            }
        );
        // Only one bound float-spelled -- the other stays a plain integer.
        query!(br"[1,2,3,4,5]", r"path(.[1.5:3])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3}]"#);
            }
        );
        query!(br"[1,2,3,4,5]", r"path(.[1:3.5])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1,"end":3.5}]"#);
            }
        );
        // An open bound stays `null`, not a fabricated `0`/length.
        query!(br"[1,2,3,4,5]", r"path(.[-1.5:])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":-1.5,"end":null}]"#);
            }
        );
        // A genuinely dynamic bound (`.[$a:$b]`) resolves through the same
        // `Expr::SliceExpr` machinery as the literal non-whole case above,
        // confirmed here via a variable binding rather than a literal.
        query!(br"[1,2,3,4,5]", r"((1.5) as $a | (3.5) as $b | path(.[$a:$b]))",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3.5}]"#);
            }
        );
        // #1088's negation rule applies identically to a slice bound: the
        // parser's own `-1 * <literal>` split destroys jq's literal
        // spelling before the slice is ever built, so the bound becomes a
        // computed double -- which happens to *render* bare when whole
        // (jq's own convention for a computed value, not evidence the key
        // was dropped; `-3.5:-1.5` below, non-whole, keeps its `.5`).
        query!(br"[1,2,3,4,5]", r"path(.[-3.0:-1.0])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":-3,"end":-1}]"#);
            }
        );
        query!(br"[1,2,3,4,5]", r"path(.[-3.5:-1.5])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":-3.5,"end":-1.5}]"#);
            }
        );
        // The resolved *value* (not just the path component) is unaffected
        // -- reading, writing, and round-tripping through `setpath`/
        // `getpath` all still use the truncated/rounded i64 bounds exactly
        // as before.
        query!(br"[1,2,3,4,5]", r".[1.5:3.5]",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[2,3,4]");
            }
        );
        query!(br"[1,2,3,4,5]", r"path(.[1.5:3.5]) as $p | getpath($p)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), "[2,3,4]");
            }
        );
        query!(br"[1,2,3,4,5]", r#".[1.5:3.5] = ["x"]"#,
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[1,"x",5]"#);
            }
        );
    }

    /// #1326: `Expr::SliceNumber` needs a rebuild arm in every AST walker
    /// that reconstructs a filter's body, the same way #1088 already added
    /// one for `Expr::IndexNumber` -- `substitute_var` (`E as $x | body`),
    /// `expand_func_calls` (inlining a `def`), and `substitute_func_param`
    /// (substituting a parameterized `def`'s own argument). Each jq-level
    /// case here is end-to-end correct (oracle-verified against real jq
    /// 1.7.1), but doesn't exercise these three functions' own rebuild
    /// arms directly -- `path()` resolution apparently never routes a
    /// `def`/`as`-bound body through them for these shapes, so the
    /// dedicated direct-call tests just below are what actually pin the
    /// arms themselves; these stay as end-to-end sanity checks.
    #[test]
    fn test_slice_number_survives_def_and_as_binding_1326() {
        query!(br"[1,2,3,4,5]", r"path((1) as $x | .[1.5:3.5])",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3.5}]"#);
            }
        );
        query!(br"[1,2,3,4,5]", r"def f: .[1.5:3.5]; path(f)",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3.5}]"#);
            }
        );
        query!(br"[1,2,3,4,5]", r"def f(x): x | .[1.5:3.5]; path(f(.))",
            QueryResult::Owned(v) => {
                assert_eq!(v.to_json(), r#"[{"start":1.5,"end":3.5}]"#);
            }
        );
    }

    /// #1326: direct calls into `substitute_var`/`expand_func_calls`/
    /// `substitute_func_param` with a hand-built `Expr::SliceNumber`,
    /// pinning each walker's own rebuild arm regardless of whether any
    /// particular jq-level construct happens to route through it today --
    /// a `def`/`as`-bound body containing a bare `Expr::SliceNumber` is
    /// exactly the shape each function's own doc comment describes
    /// walking past.
    #[test]
    fn test_ast_rebuild_walkers_clone_slice_number_directly_1326() {
        let slice_number = Expr::SliceNumber {
            start: Some(1),
            end: Some(3),
            start_key: Some(NumberKey::Literal(1.5, "1.5".into())),
            end_key: None,
        };
        assert_eq!(
            substitute_var(&slice_number, "x", &OwnedValue::Int(9)),
            slice_number
        );
        assert_eq!(
            expand_func_calls(&slice_number, "f", &[], &Expr::Identity, None, 0),
            slice_number
        );
        assert_eq!(
            substitute_func_param(&slice_number, "x", &Expr::Identity),
            slice_number
        );
    }

    /// #1326 review: adding `Expr::SliceNumber` alongside `Expr::Slice` in
    /// `delete_expr_array_paths`'s error-construction match exposed that
    /// `Expr::IndexNumber` had no arm of its own there either -- a
    /// pre-existing #1088 gap (a float-spelled index reaching this path
    /// would have hit the catch-all `unreachable!()` instead of the same
    /// error `Expr::Index` gets), closed as a byproduct rather than a
    /// deliberate target. Called directly rather than through a jq query:
    /// `5 | del(.[2.0])`-shaped repros exit through a different,
    /// higher-level dispatch before ever reaching this specific match.
    #[test]
    fn test_delete_expr_array_paths_reports_index_number_like_plain_index_1326() {
        let steps = [DeleteStep {
            component: Expr::IndexNumber {
                idx: 2,
                key: NumberKey::Literal(2.0, "2.0".into()),
            },
            optional: false,
        }];
        let err =
            delete_expr_array_paths(OwnedValue::Int(5), &[&steps], 0).expect_err("not an array");
        assert_eq!(err.message, "Cannot index number with number");
    }

    // #694: `collect_owned()`/`eval_owned_multi` silently dropped a
    // `Partial`'s trailing `Control::Error`/`Control::Break`, keeping only
    // its prefix as if evaluation had completed normally -- so a mid-stream
    // error/break through any of ~15 call sites (dynamic indexing, path
    // resolution, `recurse`, `as`-binding, ...) silently wrote a value or
    // continued a traversal instead of raising the error jq raises. These
    // pin the issue's own repros plus a representative sample of the other
    // fixed call sites, and a guard that `|=` itself was deliberately left
    // unfixed (see `eval_owned_multi_first`).

    #[test]
    fn test_dynamic_index_assignment_propagates_partial_error_694() {
        // Issue #694's primary repro. Confirmed against real jq 1.7.1:
        // `echo '{"a":{}}' | jq '.a[(foreach (1,2) as $x ("x"; .+"y",
        // error("boom")))] = 99'` raises "boom" -- before this fix,
        // succinctly silently wrote `{"a":{"xy":99}}` and exited 0.
        query!(
            br#"{"a":{}}"#,
            r#".a[(foreach (1,2) as $x ("x"; .+"y", error("boom")))] = 99"#,
            QueryResult::Error(e) | QueryResult::Partial(_, Control::Error(e)) => {
                assert_eq!(e.message, "boom");
            }
        );
    }

    #[test]
    fn test_recurse_propagates_partial_error_from_condition_694() {
        // Issue #694's second repro. Confirmed against real jq 1.7.1: errors
        // with "boom" -- before this fix, succinctly silently continued the
        // traversal to `[null,1]`, contradicting `builtin_recurse`'s own
        // doc comment ("An error aborts the whole traversal", #636 — reworded
        // by #842, which added the nuance that `f`'s own partial fan-out is
        // drained before the error is actually raised).
        query!(
            b"null",
            r#"[recurse(if . == null then (foreach (1,2) as $x (0; .+$x, error("boom"))) else empty end)]"#,
            QueryResult::Error(e) | QueryResult::Partial(_, Control::Error(e)) => {
                assert_eq!(e.message, "boom");
            }
        );
    }

    #[test]
    fn test_recurse_f_keeps_own_partial_fanout_before_error_842() {
        // Issue #842's primary repro (value position, streamed — not
        // collected into `[...]`, which is atomic in both jq and succinctly
        // and not part of this bug). Confirmed against real jq 1.7.1:
        // `echo '{"a":1,"b":2}' | jq -c 'recurse(if . == {"a":1,"b":2} then
        // (.a, .b[0]) else empty end)'` prints the root *and* `1` (the `.a`
        // branch of `f`'s fan-out, produced before `.b[0]` errors) before
        // erroring. Before this fix, succinctly printed only the root,
        // dropping `1`.
        assert_eq!(
            outputs(
                br#"{"a":1,"b":2}"#,
                r#"recurse(if . == {"a":1,"b":2} then (.a, .b[0]) else empty end)"#
            ),
            vec![r#"{"a":1,"b":2}"#, "1"]
        );
        query!(
            br#"{"a":1,"b":2}"#,
            r#"recurse(if . == {"a":1,"b":2} then (.a, .b[0]) else empty end)"#,
            QueryResult::Partial(prefix, Control::Error(e)) => {
                assert_eq!(
                    prefix.iter().map(OwnedValue::to_json).collect::<Vec<_>>(),
                    vec![r#"{"a":1,"b":2}"#.to_string(), "1".to_string()]
                );
                assert!(e.message.contains("Cannot index number with number"));
            }
        );
    }

    #[test]
    fn test_recurse_f_keeps_own_partial_fanout_subtree_before_error_842() {
        // A deeper repro of #842: the successfully-produced child (`.child`)
        // itself has further children under recursion, so this checks that
        // the *entire* subtree reached from `f`'s own partial fan-out is
        // visited before the error, not just the bare partial value.
        // Confirmed against real jq 1.7.1:
        // `echo '{"child":{"child":"leaf","leafflag":true},"bad":3}' | jq -c
        // 'recurse(if (.|type)=="object" then (.child, .bad[0]) else empty
        // end)'` prints the root, `{"child":"leaf","leafflag":true}`,
        // `"leaf"`, and `null` (in that order) before erroring.
        assert_eq!(
            outputs(
                br#"{"child":{"child":"leaf","leafflag":true},"bad":3}"#,
                r#"recurse(if (.|type)=="object" then (.child, .bad[0]) else empty end)"#
            ),
            vec![
                r#"{"child":{"child":"leaf","leafflag":true},"bad":3}"#,
                r#"{"child":"leaf","leafflag":true}"#,
                r#""leaf""#,
                "null",
            ]
        );
    }

